import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百一十六章 独自修行的真正含义","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/216第二百一十六章 独自修行的真正含义.md","filePath":"meditation/巴利文大藏经/216第二百一十六章 独自修行的真正含义.md"}'),o={name:"meditation/巴利文大藏经/216第二百一十六章 独自修行的真正含义.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百一十六章-独自修行的真正含义" tabindex="-1">第二百一十六章 独自修行的真正含义 <a class="header-anchor" href="#第二百一十六章-独自修行的真正含义" aria-label="Permalink to &quot;第二百一十六章 独自修行的真正含义&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部21相应10经/名叫上座经(比丘相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在王舍城栗鼠饲养处的竹林中，那个时候，有一位出家修行二十年以上的长老比丘，他是独来独往的修行人，他独自的修行，他也称赞那些独自修行的人，他中午的时候，独自到乡村或城镇化缘饭食，他独自的吃饭食，又独自的返回到偏僻密林中的茅草棚里静坐。他疲倦的时候，静坐昏沉、想打瞌睡的时候，就会独自在一定的路径上来回、往返的走动，以此来让自己的内心恢复清净的境界。</p><p>那个时候，众多的比丘们来到佛陀的住所，他们顶礼佛陀后，就在一旁坐下，他们对佛陀说：“世尊，有一位长老比丘，他独自的修行，他也称赞那些独自修行的人。”</p><p>于是，佛陀就叫来一位比丘对他说：“比丘！你以如来的名义去请这位长老比丘到如来这里来，你可以这样对他说：「长老比丘，世尊请你去见他。」”</p><p>这位比丘回答：“世尊，我现在就去请这位长老比丘到您这里来。”</p><p>没有过多久，这位长老比丘就来到佛陀的住处，他顶礼佛陀后，就在一旁坐下，佛陀对这位长老比丘说：“上座（出家修行二十年以上的出家人）！你独自的修行，也称赞那些独自修行的人，真是这样的吗？”</p><p>这位长老比丘回答：“世尊，我确实是在独自的修行，我也称赞那些独自修行的人。”</p><p>佛陀说：“上座！你能告诉如来，你是如何独自修行的吗？你能告诉如来，你是如何称赞独自修行的人的吗？”</p><p>这位长老比丘回答：“世尊，是这样的，我中午独自一人到乡村或城镇化缘饭食，我独自的吃饭食，又独自的返回偏僻密林中的茅草棚里静坐。我疲倦的时候，静坐昏沉、想打瞌睡的时候，就会独自在一定的路径上来回、往返的走动，以此来让自己的内心恢复清净的境界。世尊，我就是这样独自修行的，我也称赞那些这样独自去修行的人。”</p><p>佛陀说：“上座！如来现在已经明白了，你告诉如来的只是你独来独往的行为，现在如来将会为你讲说如何独自的修行才是圣者所赞叹的，才是真正名副其实、圆满的独自修行。你要认真的听，你要仔细的思考。”</p><p>这位长老比丘回答：“世尊，我会认真听您说法的，我会仔细思考的，恭请世尊您为我说法。”</p><p>佛陀说：“上座！不再怀念回忆过去的事物事情，不再执着和挂念过去的事物事情，不再内心中生起过去事物事情的念想；对未来的事物事情不会有任何的期待，对未来的事物事情不会生起任何的幻想，不会去执着和挂念未来的事物事情，不会在内心中生起未来事物事情的念想。对现在的事物事情不会执着和挂念，不会在内心中生起现在事物事情的念想。已经不会再执着和挂念过去、未来、现在的事物事情，已经不会再执着和挂念过去、未来、现在生起的任何念想，已经灭尽了对世间一切事物的贪欲，已经灭尽了自我真实存在的念想。欲望已经完全被驱散，贪欲已经灭除殆尽，对自我存在的念想已经灭尽。上座！这样的修行才是圣者所赞叹的，才是真正名副其实、圆满的独自修行。</p><p>不执着和挂念世间一切的事物，不挂念和执着内心生起的一切念想，甚至于不在内心中生起任何的念想，这些人就是征服欲望魔军的胜利者，这些人就是彻底明白世间真相、规则，有大智慧的修行人，这些人就是善于用正确的智慧去修行的人，他们不会被世间任何的事物、念想、修行方法束缚捆绑，甚至于他们连如来的正法都不会去执着和挂念，他们连如来的正法都不会在内心中生起，他们不会被世间一切的事物、念想、修行方法污染、困扰。他们灭尽了一切的贪爱、渴爱，从世间一切的事物、念想、修行方法中解脱了出来，他们的内心清净无染，他们除灭了一切的烦恼和痛苦。他们能从生死轮回中永远的解脱出来，最终证悟不生不灭涅槃的境界，如来就说这样的修行人，他们才是真正、名副其实独自修行的人。”</p><p>这时，佛陀说偈言：</p><p>「一切之胜者，</p><p>一切之智者，</p><p>乃至善智者，</p><p>不染一切法。</p><p>舍爱尽解脱，</p><p>此谓独住者。」</p><p>佛陀说法后，这位长老比丘和在场听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',23)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
